57.    /**
58.     * 封装调用库存代码
59.     *
60.     * @param billTypeId                  单据标识
61.     * @param bills                       单据模型
62.     * @param opKey                       操作类型
63.     * @param isvOrderInventoryFieldModel 字段模型
64.     * @param option                      操作
65.     * @param result                      操作结果
66.     * @param opSign                      入库还是出库 入库传1 出库传-1
67.     * @param bInvCheck                   单据更新库存时传false,库存校对调用传true
67.     */
68.    public static List<DynamicObject> setInventory(String billTypeId, DynamicObject[] bills, String opKey, IsvOrderInventoryFieldModel isvOrderInventoryFieldModel, BigDecimal opSign
69.        , OperateOption option, OperationResult result,boolean bInvCheck) {
70.        if (option == null) {
71.            option = OperateOption.create();
72.        }
73.        if (result == null) {
74.            result = new OperationResult();
75.        }
76.        // 库存操作
77.        InventoryBatchBO inventoryBatchBo = new InventoryBatchBO(opKey, bInvCheck ? InvCallTypeEnum.CHECK : InvCallTypeEnum.BILL, option, bills, result);
78.        InventoryService inventoryService = new InventoryServiceImpl();
79.        List<IsvOrderInventoryModel> isvList = new ArrayList<>();
80.        //遍历单据，组装库存模型
81.        for (DynamicObject bill : bills) {
82.            //本身单据商品分录单据体标识
83.            DynamicObjectCollection entryList = bill.getDynamicObjectCollection("material_entity");
84.            //遍历分录组装模型  计算出实际的基本数量 和浮动基本数量(固定多单位不传)，
85.            // 如果有下推，在下推单据的操作插件里面需要计算订单的差异值，减少对应的预计量
86.            for (DynamicObject entry : entryList) {
87.                isvList.add(IsvInvUtils.buildIsvOrderInventoryModel(billTypeId, bill, entry, isvOrderInventoryFieldModel, entry.getBigDecimal("baseqty").multiply(opSign), entry.getBigDecimal("deffloatqty").multiply(opSign)));
88.            }
89.        }
90.        InventoryBatchVO inventoryResult = inventoryService.setISVOrderBatchInventory(inventoryBatchBo, isvList);
91.        return inventoryResult.getSuccessBills();
92.    }
