94.    /**
95.     * 获取单据数据
96.     *
97.     * @param billType 单据类型
98.     */
99.    public static DynamicObject[] getOrderBillInfo(String billType) {
100.        DynamicObject[] bills;
101.        int DEF_PAGE_SIZE = 5000;
102.        String auditStatus = "C";//已审核
103.        //根据实际情况过滤需要统计的订单数据 如果要过滤部分分录，例如关闭的分录，也需要在后续组装模型的时候排除
104.        QFilter[] filters = new QFilter[]{
105.            new QFilter(InvBillConst.BILLSTATUS, QFilter.equals, auditStatus)
106.        };
107.        List<Object> primaryKeys = QueryServiceHelper.queryPrimaryKeys(billType, filters, null, -1);
108.        //总记录数
109.        int totalSize = new HashSet<>(primaryKeys).size();
110.        //总页数
111.        int pageCount = totalSize / DEF_PAGE_SIZE;
112.        if (totalSize % DEF_PAGE_SIZE != 0) {
113.            pageCount += 1;
114.        }
115.        int pageIndex = 0;
116.        //无记录
117.        if (totalSize == 0) {
118.            return null;
119.        }
120.
121.        //根据实际字段查询
122.        String fields = "billno," +
123.            "material_entity.materialid,material_entity.auxpropid,material_entity.unittype," +
124.            "material_entity.baseqty," +
125.            "material_entity.deffloatqty,material_entity.seq," +
126.            "material_entity.auxunittype";
127.        //无需分页
128.        if (pageCount == 1) {
129.            bills = BusinessDataServiceHelper.load(billType, fields, filters, "id", pageIndex, DEF_PAGE_SIZE);
130.        } else {
131.            //分页逻辑
132.            bills = new DynamicObject[totalSize];
133.            while (pageIndex < pageCount) {
134.                DynamicObject[] divBills = BusinessDataServiceHelper.load(billType, fields, filters, "id", pageIndex, DEF_PAGE_SIZE);
135.                System.arraycopy(divBills, 0, bills, pageIndex * DEF_PAGE_SIZE, divBills.length);
136.                pageIndex++;
137.            }
138.        }
139.        return bills;
140.    }
141.
142.    /**
143.     * 分批调用库存更新
144.     *
145.     * @param bills       单据信息
146.     * @param billTypeId  单据类型
147.     * @param maxPageSize 分批大小
148.     */
149.    public static void checkInv(DynamicObject[] bills, String billTypeId, int maxPageSize) {
150.        if (bills == null || 0 == bills.length) {
151.            return;
152.        }
153.        String audit = "audit";//审核操作
154.        //入库1 出库 -1
155.        BigDecimal opSign = BigDecimal.valueOf(1);
156.        IsvOrderInventoryFieldModel isvOrderInventoryFieldModel = IsvTestBuildInventoryUtil.buildIsvOrderFieldModel();
157.        if (maxPageSize <= 0) {
158.            throw new KDBizException("参数[ONCE_PROC_MAX_BILLS]必须大于0");
159.        }
160.        if (maxPageSize >= bills.length) {
161.            //单据不多于最大处理量
162.            IsvTestBuildInventoryUtil.setInventory(billTypeId, bills, audit, isvOrderInventoryFieldModel, opSign, null, null,true);
163.        } else {
164.            //单据分批计算逻辑
165.            int num = 0;
166.            while (true) {
167.                int from = maxPageSize * num;
168.                int to = maxPageSize * (num + 1);
169.                if (to > bills.length) {
170.                    to = bills.length;
171.                }
172.                //下标从0开始，包含from，不包含to
173.                DynamicObject[] divBills = Arrays.copyOfRange(bills, from, to);
174.                IsvTestBuildInventoryUtil.setInventory(billTypeId, divBills, audit, isvOrderInventoryFieldModel, opSign, null, null,true);
175.                if (to >= bills.length) {
176.                    break;
177.                }
178.                num++;
179.            }
180.        }
181.    }
182.}
