package com.jdy.cmbc.formplugin;

import com.jdy.cmbc.common.billtemplate.util.ToolbarConst;
import com.jdy.cmbc.formplugin.share.Utils.BillApiNumberEnum;
import com.jdy.cmbc.formplugin.share.Utils.BillShareHelper;
import com.jdy.cmbc.formplugin.share.Utils.ShareConstant;
import com.jdy.cmbc.formplugin.share.Utils.ShowQrCodeUtil;
import kd.bos.dataentity.resource.ResManager;
import kd.bos.dataentity.utils.StringUtils;
import kd.bos.entity.datamodel.ListSelectedRowCollection;
import kd.bos.form.control.events.BeforeItemClickEvent;
import kd.bos.form.control.events.ItemClickEvent;
import kd.bos.list.BillList;
import kd.bos.metadata.dao.MetaCategory;
import kd.bos.metadata.dao.MetadataDao;
import kd.bos.metadata.form.FormMetadata;
import xc.bos.form.plugin.XcAbstractFormPlugin;

import java.util.EventObject;
import java.util.HashMap;

public class testBillShare extends XcAbstractFormPlugin {

    @Override
    public void beforeItemClick(BeforeItemClickEvent evt) {
        super.beforeItemClick(evt);
    }

    @Override
    public void registerListener(EventObject e) {
        super.registerListener(e);
        this.addItemClickListeners("common_tool");
    }

    @Override
    public void itemClick(ItemClickEvent evt) {
        super.itemClick(evt);
        String entityNumber = BillShareHelper.getEntityId(this.getView());
        String id = MetadataDao.getIdByNumber(entityNumber, MetaCategory.Form);
        FormMetadata formMeta = (FormMetadata) MetadataDao.readRuntimeMeta(id, MetaCategory.Form);
        String urlNumber = formMeta.getBizappNumber() + "/" + entityNumber;
        String billDetailUrlNumber = urlNumber + "detail";
        Long pkid = (Long) this.getView().getModel().getDataEntity().getPkValue();
        HashMap<String, Object> customHashMap = new HashMap<>();
        String shareBillDomian = System.getProperty("shareBillDomian", ShareConstant.PREFIX_URL);
        #ShareConstant.SHARE_BILL_DOMIAN 为分享的链接域名配置，这个是规定的key，后面的shareBillDomian值就是自定义的域名值
        customHashMap.put(ShareConstant.SHARE_BILL_DOMIAN, shareBillDomian);
        #urlNumber为自定义的路由，pkid是urlNumber这个路由的请求参数（请求参数最后会被加密成一串数字）
        customHashMap.put(urlNumber, String.valueOf(pkid));
        #billDetailUrlNumber为自定义的路由，pkid是billDetailUrlNumber这个路由的请求参数,（请求参数最后会被加密成一串数字）
        customHashMap.put(billDetailUrlNumber, String.valueOf(pkid));
        if (StringUtils.equals(ToolbarConst.BARITEM_SHARE, evt.getItemKey())) {
            try {
                ShowQrCodeUtil.showQRCode(this.getView(), customHashMap);
            } catch (Exception e) {
                this.getView().showErrorNotification(ResManager.loadKDString("分享失败：%s", "PurBaseFormPlugin_6", "scm-pur-formplugin", e.getMessage()));
            }
            return;
        }
    }
}

